        present = {str(row.get("name") or "") for row in (state.get("restaurants") or [])
                   if isinstance(row, Mapping)}
        missing = [name for name in expected if name not in present]
        if missing:
            raise WindowsPreparationError(
                "the seeded store is missing restaurants: " + ", ".join(missing))
        return f"{prepared}; {len(present)} seeded restaurants are present"

