def describe_state(state: Mapping[str, Any]) -> str:
    """Summarise the seeded store for the result metadata."""
    return json.dumps({
        "restaurants": len(state.get("restaurants") or []),
        "orders": len(state.get("createdOrders") or []),
        "users": len(state.get("users") or []),
    }, ensure_ascii=False)
